// Scratch helper (raw WebSocket): node tv.mjs apps | key KEY_A KEY_B ... | launch <appId>
import https from 'node:https'; import crypto from 'node:crypto'; import fs from 'node:fs';
const ip = '192.168.68.109', tokFile = new URL('./token-familyroom.txt', import.meta.url);
const tok = fs.existsSync(tokFile) ? fs.readFileSync(tokFile, 'utf8').trim() : '';
const name = Buffer.from('TV Tuneup').toString('base64');
const [cmd, ...args] = process.argv.slice(2);
const sleep = ms => new Promise(r => setTimeout(r, ms));
function frame(str) { const p = Buffer.from(str), m = crypto.randomBytes(4); let h;
  if (p.length < 126) h = Buffer.from([0x81, 0x80 | p.length]);
  else { h = Buffer.alloc(4); h[0] = 0x81; h[1] = 0x80 | 126; h.writeUInt16BE(p.length, 2); }
  return Buffer.concat([h, m, p.map((b, i) => b ^ m[i % 4])]); }
let buf = Buffer.alloc(0);
function* frames() { for (;;) { if (buf.length < 2) return; let len = buf[1] & 0x7f, off = 2;
  if (len === 126) { if (buf.length < 4) return; len = buf.readUInt16BE(2); off = 4; }
  else if (len === 127) { if (buf.length < 10) return; len = Number(buf.readBigUInt64BE(2)); off = 10; }
  if (buf.length < off + len) return; const op = buf[0] & 0x0f, data = buf.slice(off, off + len); buf = buf.slice(off + len);
  if (op === 1) yield data.toString(); } }
const req = https.request({ host: ip, port: 8002, rejectUnauthorized: false,
  path: `/api/v2/channels/samsung.remote.control?name=${name}${tok ? '&token=' + tok : ''}`,
  headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': crypto.randomBytes(16).toString('base64') } });
const timer = setTimeout(() => { console.log('TIMEOUT'); process.exit(2); }, 20000);
req.on('upgrade', (res, sock) => {
  const send = o => sock.write(frame(JSON.stringify(o)));
  sock.on('data', async d => { buf = Buffer.concat([buf, d]); for (const t of frames()) { if (process.env.DBG) console.log('RX', t.slice(0,300)); const m = JSON.parse(t);
    if (m.event === 'ms.channel.connect') {
      if (m.data?.token && m.data.token !== tok) fs.writeFileSync(tokFile, m.data.token);
      if (cmd === 'apps') send({ method: 'ms.channel.emit', params: { event: 'ed.installedApp.get', to: 'host' } });
      else if (cmd === 'launch') send({ method: 'ms.channel.emit', params: { event: 'ed.apps.launch', to: 'host', data: { appId: args[0], action_type: 'DEEP_LINK' } } });
      else if (cmd === 'key') { for (const k of args) { send({ method: 'ms.remote.control', params: { Cmd: 'Click', DataOfCmd: k, Option: 'false', TypeOfRemote: 'SendRemoteKey' } }); console.log('sent', k); await sleep(800); } process.exit(0); }
      else process.exit(0);
    } else if (m.event === 'ed.installedApp.get') { for (const a of m.data.data) console.log(a.appId.padEnd(30), a.name); process.exit(0); }
    else if (m.event === 'ms.channel.unauthorized') { console.log('DENIED'); process.exit(3); }
    else { console.log('event', m.event, JSON.stringify(m.data ?? '').slice(0, 200)); if (cmd === 'launch') process.exit(0); } } });
});
req.on('response', r => { console.log('HTTP', r.statusCode); process.exit(1); });
req.on('error', e => { console.log('ERR', e.message); process.exit(1); }); req.end();
